import java.util.Set;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.VariableScopeChange;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryOptimizer;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractSimpleQueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;
import org.eclipse.rdf4j.query.algebra.helpers.collectors.VarNameCollector;

/**
 * Removes identity projections only when the child's exported outputs and inherited inputs prove that no bindings would
 * be exposed or lost.
 */
public class ProjectionRemovalOptimizer implements QueryOptimizer {

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings);
		tupleExpr.visit(new ProjectionFinder(analysis));
	}

	private static class ProjectionFinder extends AbstractSimpleQueryModelVisitor<RuntimeException> {

		private final QueryAlgebraBindingAnalysis analysis;

		private ProjectionFinder(QueryAlgebraBindingAnalysis analysis) {
			super(true);
			this.analysis = analysis;
		}

		@Override
		public void meet(Projection projection) throws RuntimeException {
			super.meet(projection);

			if (!isIdentityProjection(projection)) {
				return;
			}

			TupleExpr child = projection.getArg();
			QueryAlgebraBindingAnalysis.ReadOnlyContext input = analysis.contextAt(projection);
			QueryAlgebraBindingAnalysis.OutputFacts childFacts = analysis.outputFacts(child,
					analysis.contextAt(child));
			Set<String> projectedNames = projection.getBindingNames();
			if (!childFacts.possibleOutputsKnown() || !childFacts.guaranteedOutputsKnown()
					|| !childFacts.possibleOutputs().equals(projectedNames)
					|| !child.getBindingNames().equals(projectedNames)
					|| !projectedNames.containsAll(childFacts.inheritedInputNames())
					|| !projectedNames.containsAll(input.maybeBoundNames())
					// A variable a sub-select body reads but does not project is local to the sub-select; removing the
					// projection would expose it to bindings from outside the sub-select.
					|| projection.isSubquery() && !projectedNames.containsAll(VarNameCollector.process(child))) {
				return;
			}

			// Outer SELECT projections still define the public result binding domain. An opaque or otherwise
			// non-repeatable child can expose inherited/internal bindings that its declared output names omit.
			if (!AlgebraEvaluationSafety.isRepeatable(child)) {
				return;
			}

			if (projection.getParentNode() == null) {
				return;
			}
			if (projection.isVariableScopeChange() && child instanceof VariableScopeChange scopeChange) {
				scopeChange.setVariableScopeChange(true);
			}
			projection.getParentNode().replaceChildNode(projection, child);
			analysis.invalidate();
		}

		private boolean isIdentityProjection(Projection projection) {
			for (ProjectionElem element : projection.getProjectionElemList().getElements()) {
				if (element.getSourceExpression() != null || element.hasAggregateOperatorInExpression()) {
					return false;
				}
				String source = element.getName();
				String target = element.getProjectionAlias().orElse(source);
				if (!source.equals(target)) {
					return false;
				}
			}
			return !projection.getProjectionElemList().getElements().isEmpty();
		}
	}
}
